//! Conformance of the Rust ISA table with the Python model (`npu_model`).
//!
//! `tests/data/isa_golden.txt` is generated by `scripts/gen_isa_golden.py`; see that script for
//! the line format and how operand vectors are chosen.

use std::collections::{HashMap, HashSet};

use npu_model_rs::isa::{Access, BuildError, DecodeError, Exu, Instruction, Mnemonic, OperandKind};

const GOLDEN: &str = include_str!("data/isa_golden.txt");

fn records(tag: &'static str) -> impl Iterator<Item = Vec<&'static str>> {
    GOLDEN
        .lines()
        .map(|line| line.split_whitespace().collect::<Vec<_>>())
        .filter(move |fields| fields.first() == Some(&tag))
        .map(|fields| fields[1..].to_vec())
}

fn hex(s: &str) -> u32 {
    u32::from_str_radix(s.trim_start_matches("0x"), 16).unwrap()
}

fn python_exu(exu: Exu) -> &'static str {
    match exu {
        Exu::Scalar => "SCALAR",
        Exu::Vector => "VECTOR",
        Exu::Xlu => "XLU",
        Exu::MatrixSystolic => "MATRIX_SYSTOLIC",
        Exu::MatrixInner => "MATRIX_INNER",
        Exu::Dma => "DMA",
        Exu::Lsu => "LSU",
    }
}

fn python_access(access: Option<Access>) -> &'static str {
    match access {
        None => "immediate",
        Some(Access::Read) => "read",
        Some(Access::Write) => "write",
        Some(Access::ReadWrite) => "readwrite",
    }
}

#[test]
fn specs_match_python() {
    let mut problems = Vec::new();
    let mut seen = HashSet::new();
    for rec in records("spec") {
        let name = rec[0];
        let Ok(mnemonic) = name.parse::<Mnemonic>() else {
            problems.push(format!("{name}: in Python but not in the Rust table"));
            continue;
        };
        seen.insert(mnemonic);
        let spec = mnemonic.spec();
        let rust_operands: Vec<String> = spec
            .operands
            .iter()
            .map(|o| format!("{}:{}", o.name, python_access(o.access)))
            .collect();
        let rust = (
            format!("{:?}", spec.format),
            python_exu(spec.exu),
            if spec.functional { "1" } else { "0" },
            spec.match_bits,
            spec.mask,
            rust_operands.join(" "),
        );
        let python = (
            rec[1].to_owned(),
            rec[2],
            rec[3],
            hex(rec[4]),
            hex(rec[5]),
            rec[6..].join(" "),
        );
        if rust != python {
            problems.push(format!("{name}:\n  rust   {rust:x?}\n  python {python:x?}"));
        }
    }
    for &mnemonic in Mnemonic::ALL {
        if !seen.contains(&mnemonic) {
            problems.push(format!("{mnemonic}: in the Rust table but not in Python"));
        }
    }
    assert!(
        problems.is_empty(),
        "{} mismatches:\n{}",
        problems.len(),
        problems.join("\n")
    );
}

#[test]
fn encodings_match_python() {
    let mut checked = 0;
    let mut rejected = 0;
    for rec in records("enc") {
        let mnemonic: Mnemonic = rec[0].parse().unwrap();
        let word = hex(rec[1]);
        let values: Vec<(&str, i64)> = rec[2..]
            .iter()
            .map(|kv| {
                let (k, v) = kv.split_once('=').unwrap();
                (k, v.parse().unwrap())
            })
            .collect();
        let spec = mnemonic.spec();
        let context = format!("{} 0x{word:08x} {values:?}", spec.mnemonic);

        // m63 can't name a register pair; Python only catches that at exec time.
        let bad_pair = spec
            .operands
            .iter()
            .any(|o| o.kind == OperandKind::MRegPair && values.contains(&(o.name, 63)));
        if bad_pair {
            assert!(
                matches!(
                    Instruction::from_named(mnemonic, &values),
                    Err(BuildError::Operand { .. })
                ),
                "{context}: m63 accepted as a register pair"
            );
            assert_eq!(
                Instruction::decode(word),
                Err(DecodeError::BadOperand {
                    word,
                    mnemonic: spec.mnemonic
                }),
                "{context}"
            );
            rejected += 1;
            continue;
        }

        let built =
            Instruction::from_named(mnemonic, &values).unwrap_or_else(|e| panic!("{context}: {e}"));
        assert_eq!(built.encode(), word, "{context}: encode");
        let decoded = Instruction::decode(word).unwrap_or_else(|e| panic!("{context}: {e}"));
        assert_eq!(decoded, built, "{context}: decode");

        // Compare decoded fields by name, not just by re-encoding.
        let by_name: HashMap<&str, i64> = values.iter().copied().collect();
        for (op, bits) in spec.operands.iter().zip(decoded.operand_bits().iter()) {
            let expected = (by_name[op.name] as u32) & ((1u32 << op.kind.bits()) - 1);
            assert_eq!(*bits, expected, "{context}: operand `{}`", op.name);
        }
        checked += 1;
    }
    // Every instruction has at least two vectors that every model accepts.
    assert!(
        checked >= 2 * Mnemonic::COUNT,
        "only {checked} vectors checked"
    );
    assert!(rejected > 0, "no m63 register-pair vectors exercised");
}
